import React, { useEffect, useRef } from 'react';

interface BoldReportProps {
  apiUrl: string;      // Your backend report API endpoint
  reportName: string;  // RDL file name
  tenantId?: string;   // Tenant ID
  start?: string;      // Start date
  end?: string;        // End date
}

declare const $: any;

export const BoldReport: React.FC<BoldReportProps> = ({ apiUrl, reportName, tenantId, start, end }) => {
  const viewerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const loadViewer = () => {
      if (viewerRef.current && typeof $(viewerRef.current).boldReportViewer === 'function') {
        $(viewerRef.current).boldReportViewer({
          id: 'reportViewer',
          reportServiceUrl: `${apiUrl}?start=${start}&end=${end}&clientLocalTime=${new Date().toISOString()}`,
          reportPath: reportName,
          parameters: [
            { name: 'TenantId', value: tenantId || '00000000-0000-0000-0000-000000000000' },
          ],
          toolbarSettings: { showToolbar: true },
          height: '900px',
        });
      } else {
        setTimeout(loadViewer, 100);
      }
    };

    loadViewer();
  }, [apiUrl, reportName, tenantId, start, end]);

  return <div ref={viewerRef} style={{ width: '100%' }} />;
};
